namespace ContentOS.Domain;

public sealed class CommerceProduct : CoreRecord { public Guid TenantId { get; set; } public Guid UserId { get; set; } public Guid UniverseId { get; set; } public Guid OperationId { get; set; } public string Fingerprint { get; set; } = ""; public string Key { get; set; } = ""; public int Version { get; set; } public Guid CreationId { get; set; } public int ContentVersion { get; set; } public string ContentSha256 { get; set; } = ""; public string Kind { get; set; } = ""; public Guid? CustomerProductId { get; set; } public string SettingsJson { get; set; } = ""; public string? PackageJson { get; set; } public bool Enabled { get; set; } = true; }
public sealed class CommerceRoute : CoreRecord { public Guid TenantId { get; set; } public Guid OperationId { get; set; } public string Key { get; set; } = ""; public int Version { get; set; } public string Adapter { get; set; } = ""; public string Account { get; set; } = ""; public bool Active { get; set; } public bool Enabled { get; set; } = true; }
public sealed class CommerceOrder : CoreRecord { public Guid TenantId { get; set; } public Guid UserId { get; set; } public Guid OperationId { get; set; } public string Fingerprint { get; set; } = ""; public Guid ProductId { get; set; } public Guid RouteId { get; set; } public Guid? InstitutionId { get; set; } public Guid? PaymentOrderId { get; set; } public string State { get; set; } = "Preparing"; public DateTimeOffset? EndsUtc { get; set; } }
public sealed class CommerceDelivery : CoreRecord { public Guid TenantId { get; set; } public Guid OrderId { get; set; } public string RequestJson { get; set; } = ""; public string State { get; set; } = "Queued"; public Guid? Lease { get; set; } public DateTimeOffset? LeaseUntilUtc { get; set; } public string? Receipt { get; set; } public decimal Cost { get; set; } public string Currency { get; set; } = "INR"; }
public sealed class CommerceEffect : CoreRecord { public Guid TenantId { get; set; } public Guid DeliveryId { get; set; } public string Fingerprint { get; set; } = ""; public string OutcomeJson { get; set; } = ""; }
public sealed class CommerceInstitution : CoreRecord { public Guid TenantId { get; set; } public Guid UserId { get; set; } public Guid OperationId { get; set; } public string Name { get; set; } = ""; public string ContractReference { get; set; } = ""; }
public sealed class CommerceSeat : CoreRecord { public Guid TenantId { get; set; } public Guid InstitutionId { get; set; } public Guid UserId { get; set; } public string Cohort { get; set; } = ""; public string Role { get; set; } = "Learner"; public bool Enabled { get; set; } = true; }
public sealed class CommerceActivity : CoreRecord { public Guid TenantId { get; set; } public Guid InstitutionId { get; set; } public Guid UserId { get; set; } public Guid ProfileId { get; set; } public Guid OperationId { get; set; } public bool Completed { get; set; } }
public sealed class CommerceAudit : CoreRecord { public Guid TenantId { get; set; } public Guid OperationId { get; set; } public Guid UserId { get; set; } public Guid SubjectId { get; set; } public string Kind { get; set; } = ""; public string Fingerprint { get; set; } = ""; }
public sealed class CommerceOffer : CoreRecord { public Guid TenantId { get; set; } public Guid OperationId { get; set; } public string SettingsJson { get; set; } = ""; }
